CREATE ROLE app_owner LOGIN PASSWORD 'Owner#2026';
CREATE ROLE app_readonly NOLOGIN;
CREATE ROLE app_readwrite NOLOGIN;

CREATE ROLE ravi LOGIN PASSWORD 'Ravi#2026';
CREATE USER asha PASSWORD 'Asha#2026';
\du

GRANT app_readonly TO ravi;
GRANT app_readwrite TO asha;
\drg

CREATE SCHEMA sales;
CREATE TABLE sales.orders (
    order_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer    text    NOT NULL,
    amount      numeric(10,2) NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);
INSERT INTO sales.orders (customer, amount) VALUES
    ('Meena Traders', 1250.00),
    ('Kumar Stores',   480.50),
    ('Fresh Mart',    2999.00);

CREATE TABLE sales.refunds (
    refund_id  serial PRIMARY KEY,
    order_id   bigint NOT NULL,
    amount     numeric(10,2) NOT NULL
);

ALTER DEFAULT PRIVILEGES FOR ROLE app_owner IN SCHEMA sales
    GRANT SELECT ON TABLES TO app_readonly;
ALTER DEFAULT PRIVILEGES FOR ROLE app_owner IN SCHEMA sales
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_readwrite;
ALTER DEFAULT PRIVILEGES FOR ROLE app_owner IN SCHEMA sales
    GRANT USAGE ON SEQUENCES TO app_readwrite;

GRANT SELECT ON ALL TABLES IN SCHEMA sales TO app_readonly;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA sales TO app_readwrite;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA sales TO app_readwrite;
\ddp

CREATE TABLE sales.payments (
    payment_id  serial PRIMARY KEY,
    order_id    bigint NOT NULL,
    paid        numeric(10,2) NOT NULL
);

REVOKE CONNECT ON DATABASE shop FROM PUBLIC;
GRANT CONNECT ON DATABASE shop TO app_readonly, app_readwrite;
SELECT unnest(datacl) AS acl FROM pg_database WHERE datname = 'shop';

SELECT current_user, session_user;
SET ROLE app_readonly;
SELECT current_user, session_user;
RESET ROLE;
SET ROLE app_readwrite;

REASSIGN OWNED BY kiran TO app_owner;
DROP OWNED BY kiran;
-- repeat both commands in every other database: \c postgres, \c shop2, ...
DROP ROLE kiran;

